previewCss:
.darma-loader-darma-b17-blood-pressure-cuff { --accent: var(--loader-color, #334155); --accent-2: var(--loader-secondary-color, #38bdf8); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .6); position: relative; }
.darma-loader-darma-b17-blood-pressure-cuff .darma-loader-darma-b17-blood-pressure-cuff__arm { position: absolute; left: 2%; top: 34%; width: 58%; height: 30%; border-radius: 999px; background: linear-gradient(color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); }
.darma-loader-darma-b17-blood-pressure-cuff .darma-loader-darma-b17-blood-pressure-cuff__cuff { position: absolute; left: 14%; top: 22%; width: 34%; height: 54%; border-radius: 8px; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 22%, var(--accent-2))); transform-origin: 50% 50%; animation: darma-loader-darma-b17-blood-pressure-cuff-cuff-inflate calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-blood-pressure-cuff .darma-loader-darma-b17-blood-pressure-cuff__dial { position: absolute; right: 4%; top: 6%; width: 32%; height: 54%; border-radius: 50%; background: color-mix(in srgb, #fff 82%, var(--accent-2)); box-shadow: inset 0 0 0 3px var(--accent); }
.darma-loader-darma-b17-blood-pressure-cuff .darma-loader-darma-b17-blood-pressure-cuff__needle { position: absolute; left: 47%; top: 12%; width: 6%; height: 40%; border-radius: 3px; background: var(--accent-2); transform-origin: 50% 100%; animation: darma-loader-darma-b17-blood-pressure-cuff-cuff-needle calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-blood-pressure-cuff .darma-loader-darma-b17-blood-pressure-cuff__bulb { position: absolute; right: 10%; bottom: 2%; width: 20%; height: 30%; border-radius: 46% 46% 40% 40%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 25%, var(--accent))); transform-origin: 50% 100%; animation: darma-loader-darma-b17-blood-pressure-cuff-cuff-squeeze calc(var(--loader-speed, 1s) * .75) ease-in-out infinite; }
@keyframes darma-loader-darma-b17-blood-pressure-cuff-cuff-inflate { 0%, 6% { transform: scaleY(1) scaleX(1); } 54%, 68% { transform: scaleY(1.16) scaleX(1.06); } 92%, 100% { transform: scaleY(1) scaleX(1); } }
@keyframes darma-loader-darma-b17-blood-pressure-cuff-cuff-needle { 0%, 6% { transform: rotate(-120deg); } 54%, 68% { transform: rotate(96deg); } 92%, 100% { transform: rotate(-120deg); } }
@keyframes darma-loader-darma-b17-blood-pressure-cuff-cuff-squeeze { 0%, 100% { transform: scale(1); } 50% { transform: scale(.82, .88); } }

